contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: attempt to transferFrom `from` -> `to` of `amount` using this contract as spender
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0));
        // read allowance before
        uint256 beforeAllow = c.allowance(from, address(this));
        // read balance of from to ensure transferFrom could plausibly succeed w.r.t balance
        uint256 beforeBalanceFrom = c.balanceOf(from);

        // only attempt transferFrom in cases where beforeAllow >= amount and beforeBalanceFrom >= amount
        // so a successful call is possible (otherwise it should revert)
        require(beforeAllow >= amount);
        require(beforeBalanceFrom >= amount);

        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllow = c.allowance(from, address(this));

        // If transferFrom succeeded, allowance must have decreased by exactly amount
        assert(reverted || afterAllow + amount == beforeAllow);
    }

    receive() external payable {}
}
